import { useEffect, useState, useRef } from "react";
import { Rss, TrendingUp, TrendingDown } from "lucide-react";

interface FeedItem {
  id: number;
  headline: string;
  ticker: string;
  price: number;
  change: number;
  time: string;
  source: string;
}

const headlines = [
  "Fed signals potential rate pause amid cooling inflation data",
  "NVDA surges on record AI chip demand forecast",
  "Treasury yields drop as employment data misses estimates",
  "AAPL announces $110B buyback program, largest in history",
  "Oil prices surge on OPEC+ production cut extension",
  "Bitcoin ETF inflows hit weekly record at $1.2B",
  "TSLA deliveries beat Q4 expectations by 12%",
  "JPM upgrades semiconductor sector to overweight",
  "European markets rally on ECB dovish commentary",
  "Gold hits all-time high amid geopolitical tensions",
  "META AI revenue exceeds analyst consensus by 18%",
  "China PMI data suggests manufacturing recovery",
];

const tickers = ["AAPL", "NVDA", "TSLA", "MSFT", "GOOGL", "AMZN", "META", "JPM", "BRK.B", "SPY"];
const sources = ["Reuters", "Bloomberg", "WSJ", "CNBC", "MarketWatch"];

const generateFeedItem = (id: number): FeedItem => {
  const ticker = tickers[Math.floor(Math.random() * tickers.length)];
  const price = 100 + Math.random() * 400;
  const change = (Math.random() - 0.45) * 8;
  return {
    id,
    headline: headlines[Math.floor(Math.random() * headlines.length)],
    ticker,
    price,
    change,
    time: new Date().toLocaleTimeString("en-US", { hour12: false, hour: "2-digit", minute: "2-digit", second: "2-digit" }),
    source: sources[Math.floor(Math.random() * sources.length)],
  };
};

const IngestionFeed = () => {
  const [items, setItems] = useState<FeedItem[]>(() =>
    Array.from({ length: 8 }, (_, i) => generateFeedItem(i))
  );
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const interval = setInterval(() => {
      setItems((prev) => {
        const newItem = generateFeedItem(Date.now());
        return [newItem, ...prev.slice(0, 12)];
      });
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="glass-card rounded-2xl p-5 flex flex-col h-full">
      <div className="flex items-center gap-2 mb-4">
        <Rss className="w-4 h-4 text-muted-foreground" />
        <h2 className="text-xs font-semibold uppercase tracking-widest text-muted-foreground">
          Live Data Stream
        </h2>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-1 pr-1 min-h-0" style={{ maxHeight: 320 }}>
        {items.map((item, i) => (
          <div
            key={item.id}
            className={`p-3 rounded-xl transition-all duration-500 ${
              i === 0 ? "bg-accent/60 animate-fade-in" : "hover:bg-accent/40"
            }`}
          >
            <div className="flex items-center justify-between mb-1">
              <div className="flex items-center gap-2">
                <span className="font-mono text-xs font-bold text-foreground">{item.ticker}</span>
                <span className="font-mono text-xs font-semibold tabular-nums flex items-center gap-1">
                  {item.change >= 0 ? (
                    <TrendingUp className="w-3 h-3 text-bullish" />
                  ) : (
                    <TrendingDown className="w-3 h-3 text-bearish" />
                  )}
                  <span className={item.change >= 0 ? "text-bullish" : "text-bearish"}>
                    {item.change >= 0 ? "+" : ""}
                    {item.change.toFixed(2)}%
                  </span>
                </span>
              </div>
              <span className="font-mono text-[10px] text-muted-foreground tabular-nums">{item.time}</span>
            </div>
            <p className="text-xs text-foreground/80 leading-relaxed line-clamp-2">{item.headline}</p>
            <span className="text-[10px] text-muted-foreground mt-1 inline-block">{item.source}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

export default IngestionFeed;

