import { useEffect, useRef, useState } from "react";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Brain, Database, ShieldCheck, Target, Terminal } from "lucide-react";

type LogCategory = "INGEST" | "BRAIN" | "RISK" | "DECISION";

interface LogEntry {
  id: number;
  timestamp: string;
  category: LogCategory;
  message: string;
  rawHash: string;
  decayValue: number;
}

const categoryConfig: Record<LogCategory, { color: string; icon: typeof Brain; label: string }> = {
  INGEST: { color: "text-[hsl(220_15%_72%)]", icon: Database, label: "INGEST" },
  BRAIN: { color: "text-[hsl(42_80%_60%)]", icon: Brain, label: "BRAIN" },
  RISK: { color: "text-bullish", icon: ShieldCheck, label: "RISK" },
  DECISION: { color: "text-[hsl(42_100%_70%)]", icon: Target, label: "DECISION" },
};

const sampleMessages: Record<LogCategory, string[]> = {
  INGEST: [
    'Fetching 30d OHLCV for $AAPL...',
    'Streaming Reuters feed — 14 new articles queued',
    'Pulling $TSLA options chain from CBOE...',
    'Ingesting $NVDA pre-market volume data...',
    'Scraping SEC Form 8-K filings for $MSFT...',
    'WebSocket reconnect: Binance BTC/USDT stream',
    'Fetching 1h candles for $SPY from AlphaVantage...',
    'Parsing Bloomberg terminal snapshot for $AMZN...',
  ],
  BRAIN: [
    'VADER flagged "Surge" → Passing to DistilBERT...',
    'DistilBERT confidence: 0.91 — "Bullish" consensus',
    'NLP pipeline: 3 conflicting signals detected',
    'Ensemble model weighted average: 0.76 (Positive)',
    'VADER score −0.34 on $TSLA headline — escalating',
    'DistilBERT latency: 23ms — within SLA',
    'Cross-referencing sentiment with RSI divergence...',
    'Tokenizing earnings call transcript for $GOOGL...',
  ],
  RISK: [
    'Volatility at 42% (STABLE). Proceeding...',
    'σ calculation: 0.0187 — within tolerance band',
    'Portfolio β exposure: 1.12 — slightly aggressive',
    'Max drawdown check: −2.8% (OK, limit: −5%)',
    'VaR(95%): $312.40 — acceptable risk envelope',
    'Correlation matrix updated — $AAPL/$MSFT: 0.82',
    'Position sizing: Kelly criterion suggests 8.2%',
    'Tail risk scan: No black swan indicators detected',
  ],
  DECISION: [
    'Sentiment Weighted 0.82 → SIGNAL: BUY',
    'Consensus: HOLD — insufficient confidence (0.54)',
    'SIGNAL: SELL — Bearish divergence + neg sentiment',
    'Override: Risk module blocked BUY (σ too high)',
    'Executing paper trade: BUY 50 $AAPL @ $189.42',
    'SIGNAL: BUY — Multi-factor alignment score: 0.91',
    'Decision deferred: Awaiting Fed minutes release',
    'SIGNAL: HOLD — Market hours closed, queuing...',
  ],
};

const generateHash = () => {
  const chars = "abcdef0123456789";
  return "0x" + Array.from({ length: 16 }, () => chars[Math.floor(Math.random() * chars.length)]).join("");
};

const OracleStream = () => {
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [borderPulse, setBorderPulse] = useState<"buy" | "sell" | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const idRef = useRef(0);

  useEffect(() => {
    // Seed initial logs
    const initial: LogEntry[] = [];
    const categories: LogCategory[] = ["INGEST", "BRAIN", "RISK", "DECISION"];
    for (let i = 0; i < 8; i++) {
      const cat = categories[i % 4];
      const msgs = sampleMessages[cat];
      initial.push({
        id: idRef.current++,
        timestamp: new Date(Date.now() - (8 - i) * 3000).toLocaleTimeString("en-US", { hour12: false, hour: "2-digit", minute: "2-digit", second: "2-digit" }),
        category: cat,
        message: msgs[Math.floor(Math.random() * msgs.length)],
        rawHash: generateHash(),
        decayValue: +(Math.random() * 0.5).toFixed(4),
      });
    }
    setLogs(initial);
  }, []);

  useEffect(() => {
    const interval = setInterval(() => {
      const categories: LogCategory[] = ["INGEST", "BRAIN", "RISK", "DECISION"];
      const weights = [0.35, 0.3, 0.2, 0.15];
      const rand = Math.random();
      let cumulative = 0;
      let cat: LogCategory = "INGEST";
      for (let i = 0; i < weights.length; i++) {
        cumulative += weights[i];
        if (rand < cumulative) { cat = categories[i]; break; }
      }

      const msgs = sampleMessages[cat];
      const message = msgs[Math.floor(Math.random() * msgs.length)];

      // Check for buy/sell signals
      if (cat === "DECISION") {
        if (message.includes("BUY")) {
          setBorderPulse("buy");
          setTimeout(() => setBorderPulse(null), 1500);
        } else if (message.includes("SELL")) {
          setBorderPulse("sell");
          setTimeout(() => setBorderPulse(null), 1500);
        }
      }

      const entry: LogEntry = {
        id: idRef.current++,
        timestamp: new Date().toLocaleTimeString("en-US", { hour12: false, hour: "2-digit", minute: "2-digit", second: "2-digit" }),
        category: cat,
        message,
        rawHash: generateHash(),
        decayValue: +(Math.random() * 0.5).toFixed(4),
      };

      setLogs(prev => [...prev.slice(-60), entry]);
    }, 2200);

    return () => clearInterval(interval);
  }, []);

  // Auto-scroll
  useEffect(() => {
    if (scrollRef.current) {
      const viewport = scrollRef.current.querySelector("[data-radix-scroll-area-viewport]");
      if (viewport) {
        viewport.scrollTop = viewport.scrollHeight;
      }
    }
  }, [logs]);

  const borderClass = borderPulse === "buy"
    ? "border-bullish shadow-[0_0_20px_hsl(145_100%_39%/0.3),inset_0_0_20px_hsl(145_100%_39%/0.05)]"
    : borderPulse === "sell"
    ? "border-bearish shadow-[0_0_20px_hsl(4_100%_60%/0.3),inset_0_0_20px_hsl(4_100%_60%/0.05)]"
    : "border-[hsl(220_15%_20%)]";

  return (
    <div
      className={`h-full rounded-2xl border transition-all duration-500 flex flex-col overflow-hidden ${borderClass}`}
      style={{ background: "hsl(220 15% 11%)" }}
    >
      {/* Header */}
      <div className="px-4 py-3 border-b border-[hsl(220_15%_18%)] flex items-center gap-2 shrink-0">
        <Terminal className="w-3.5 h-3.5 text-[hsl(42_80%_60%)]" />
        <h2 className="text-[11px] font-mono font-semibold uppercase tracking-[0.15em] text-[hsl(220_15%_65%)]">
          AI Reasoning Stream
        </h2>
        <div className="ml-auto flex items-center gap-1.5">
          <div className="w-1.5 h-1.5 rounded-full bg-bullish status-dot" />
          <span className="text-[10px] font-mono text-[hsl(220_15%_50%)]">LIVE</span>
        </div>
      </div>

      {/* Feed */}
      <ScrollArea ref={scrollRef} className="flex-1">
        <div className="p-3 space-y-1">
          {logs.map((log) => {
            const cfg = categoryConfig[log.category];
            const Icon = cfg.icon;
            const isDecisionGlow = log.category === "DECISION" && (log.message.includes("BUY") || log.message.includes("SELL"));

            return (
              <Tooltip key={log.id}>
                <TooltipTrigger asChild>
                  <div
                    className={`group px-2.5 py-1.5 rounded-lg cursor-default animate-fade-in transition-colors duration-200 hover:bg-[hsl(220_15%_15%)] ${
                      isDecisionGlow ? "bg-[hsl(220_15%_14%)]" : ""
                    }`}
                  >
                    <div className="flex items-start gap-2">
                      {/* Timestamp */}
                      <span className="text-[10px] font-mono text-[hsl(220_15%_40%)] tabular-nums shrink-0 mt-0.5">
                        {log.timestamp}
                      </span>

                      {/* Category tag */}
                      <span className={`text-[10px] font-mono font-bold shrink-0 mt-0.5 flex items-center gap-1 ${cfg.color}`}>
                        <Icon className="w-3 h-3" />
                        [{cfg.label}]
                      </span>

                      {/* Message */}
                      <span
                        className={`text-[11px] font-mono leading-relaxed break-words ${
                          log.category === "DECISION" && log.message.includes("BUY")
                            ? "text-bullish font-semibold drop-shadow-[0_0_6px_hsl(145_100%_39%/0.4)]"
                            : log.category === "DECISION" && log.message.includes("SELL")
                            ? "text-bearish font-semibold drop-shadow-[0_0_6px_hsl(4_100%_60%/0.4)]"
                            : cfg.color
                        }`}
                      >
                        {log.message}
                      </span>
                    </div>
                  </div>
                </TooltipTrigger>
                <TooltipContent side="left" className="max-w-[280px] bg-[hsl(220_15%_8%)] border-[hsl(220_15%_20%)] text-[hsl(220_15%_70%)]">
                  <div className="space-y-1.5 font-mono text-[10px]">
                    <div>
                      <span className="text-[hsl(220_15%_45%)]">hash: </span>
                      <span className="text-[hsl(42_80%_60%)]">{log.rawHash}</span>
                    </div>
                    <div>
                      <span className="text-[hsl(220_15%_45%)]">decay(e⁻ᵏᐩᵗ): </span>
                      <span className="text-bullish">{log.decayValue}</span>
                    </div>
                    <div>
                      <span className="text-[hsl(220_15%_45%)]">λΔt: </span>
                      <span className="text-[hsl(220_15%_72%)]">{(log.decayValue * 1.47).toFixed(4)}</span>
                    </div>
                  </div>
                </TooltipContent>
              </Tooltip>
            );
          })}
        </div>
      </ScrollArea>

      {/* Footer */}
      <div className="px-4 py-2 border-t border-[hsl(220_15%_18%)] flex items-center justify-between shrink-0">
        <span className="text-[9px] font-mono text-[hsl(220_15%_40%)] uppercase tracking-wider">
          {logs.length} events logged
        </span>
        <span className="text-[9px] font-mono text-[hsl(220_15%_35%)]">
          Latency: {(12 + Math.random() * 8).toFixed(0)}ms
        </span>
      </div>
    </div>
  );
};

export default OracleStream;

