import { useEffect, useState } from "react";
import { Target, TrendingUp, TrendingDown, Minus } from "lucide-react";

type Signal = "BUY" | "SELL" | "HOLD";

const DecisionMatrix = () => {
  const [signal, setSignal] = useState<Signal>("BUY");
  const [confidence, setConfidence] = useState(87.3);
  const [prevSignal, setPrevSignal] = useState<Signal>("BUY");

  useEffect(() => {
    const interval = setInterval(() => {
      const rand = Math.random();
      const newSignal: Signal = rand > 0.6 ? "BUY" : rand > 0.25 ? "HOLD" : "SELL";
      setPrevSignal(signal);
      setSignal(newSignal);
      setConfidence(50 + Math.random() * 45);
    }, 7000);
    return () => clearInterval(interval);
  }, [signal]);

  const signalConfig = {
    BUY: {
      color: "text-bullish",
      bg: "bg-bullish/10",
      border: "border-bullish/20",
      glow: "glow-bullish pulse-bullish",
      icon: TrendingUp,
    },
    SELL: {
      color: "text-bearish",
      bg: "bg-bearish/10",
      border: "border-bearish/20",
      glow: "glow-bearish pulse-bearish",
      icon: TrendingDown,
    },
    HOLD: {
      color: "text-neutral-signal",
      bg: "bg-neutral-signal/10",
      border: "border-neutral-signal/20",
      glow: "",
      icon: Minus,
    },
  };

  const cfg = signalConfig[signal];
  const Icon = cfg.icon;

  return (
    <div className={`glass-card-strong rounded-2xl p-6 flex flex-col items-center justify-center transition-all duration-700 w-full ${cfg.glow}`}>
      <div className="flex items-center gap-2 mb-6">
        <Target className="w-4 h-4 text-muted-foreground" />
        <h2 className="text-xs font-semibold uppercase tracking-widest text-muted-foreground">
          Decision Matrix
        </h2>
      </div>

      <div className={`${cfg.bg} ${cfg.border} border rounded-2xl px-12 py-6 transition-all duration-500`}>
        <div className="flex items-center justify-center gap-3 mb-2">
          <Icon className={`w-8 h-8 ${cfg.color}`} />
          <span className={`font-mono text-5xl font-black tracking-tight ${cfg.color} animate-roll-up`} key={signal}>
            {signal}
          </span>
        </div>
      </div>

      <div className="mt-5 text-center">
        <div className="text-xs text-muted-foreground mb-1">Confidence Score</div>
        <div className="font-mono text-2xl font-bold tabular-nums text-foreground number-roll">
          {confidence.toFixed(1)}%
        </div>
        <div className="w-48 h-1.5 bg-border rounded-full mt-3 overflow-hidden">
          <div
            className={`h-full rounded-full transition-all duration-700 ease-out ${
              signal === "BUY" ? "bg-bullish" : signal === "SELL" ? "bg-bearish" : "bg-neutral-signal"
            }`}
            style={{ width: `${confidence}%` }}
          />
        </div>
      </div>
    </div>
  );
};

export default DecisionMatrix;

