import { Shield } from "lucide-react";

const RiskMeter = () => {
  const [volatility, setVolatility] = useState(0.23);
  const [riskLevel, setRiskLevel] = useState<"Low" | "Medium" | "High">("Medium");

  useEffect(() => {
    const interval = setInterval(() => {
      const newVol = Math.max(0.05, Math.min(0.95, volatility + (Math.random() - 0.5) * 0.1));
      setVolatility(newVol);
      setRiskLevel(newVol < 0.3 ? "Low" : newVol < 0.6 ? "Medium" : "High");
    }, 3500);
    return () => clearInterval(interval);
  }, [volatility]);

  const riskConfig = {
    Low: { color: "text-bullish", bg: "bg-bullish", label: "LOW RISK" },
    Medium: { color: "text-neutral-signal", bg: "bg-neutral-signal", label: "MED RISK" },
    High: { color: "text-bearish", bg: "bg-bearish", label: "HIGH RISK" },
  };

  const cfg = riskConfig[riskLevel];

  return (
    <div className="glass-card rounded-2xl p-5 w-full">
      <div className="flex items-center gap-2 mb-4">
        <Shield className="w-4 h-4 text-muted-foreground" />
        <h2 className="text-xs font-semibold uppercase tracking-widest text-muted-foreground">
          Risk Meter
        </h2>
      </div>

      <div className="flex items-end justify-between mb-3">
        <div>
          <div className="text-[10px] text-muted-foreground mb-0.5">σ Volatility</div>
          <div className="font-mono text-2xl font-bold tabular-nums text-foreground number-roll">
            {volatility.toFixed(4)}
          </div>
        </div>
        <span className={`font-mono text-[10px] font-bold px-2 py-1 rounded-lg ${cfg.bg}/15 ${cfg.color}`}>
          {cfg.label}
        </span>
      </div>

      {/* Risk bars */}
      <div className="flex gap-1 items-end h-10">
        {Array.from({ length: 20 }, (_, i) => {
          const threshold = i / 20;
          const active = volatility >= threshold;
          const barColor =
            threshold < 0.3
              ? "bg-bullish"
              : threshold < 0.6
              ? "bg-neutral-signal"
              : "bg-bearish";
          return (
            <div
              key={i}
              className={`flex-1 rounded-sm transition-all duration-300 ${
                active ? barColor : "bg-border"
              }`}
              style={{
                height: `${20 + i * 3.5}%`,
                opacity: active ? 0.8 + (i / 20) * 0.2 : 0.3,
              }}
            />
          );
        })}
      </div>
    </div>
  );
};

export default RiskMeter;

