import { useEffect, useState } from "react";
import { Brain } from "lucide-react";

const SentimentGauge = () => {
  const [score, setScore] = useState(72.5);
  const [model, setModel] = useState<"VADER" | "DistilBERT">("DistilBERT");

  useEffect(() => {
    const interval = setInterval(() => {
      setScore((prev) => {
        const delta = (Math.random() - 0.5) * 6;
        return Math.max(0, Math.min(100, prev + delta));
      });
      setModel(Math.random() > 0.3 ? "DistilBERT" : "VADER");
    }, 4000);
    return () => clearInterval(interval);
  }, []);

  const angle = (score / 100) * 180 - 90; // -90 to 90 degrees
  const getColor = () => {
    if (score >= 65) return "text-bullish";
    if (score <= 35) return "text-bearish";
    return "text-neutral-signal";
  };

  const getLabel = () => {
    if (score >= 65) return "Bullish";
    if (score <= 35) return "Bearish";
    return "Neutral";
  };

  // SVG arc for the gauge
  const radius = 80;
  const cx = 100;
  const cy = 95;

  const polarToCartesian = (angleDeg: number) => {
    const rad = ((angleDeg - 180) * Math.PI) / 180;
    return {
      x: cx + radius * Math.cos(rad),
      y: cy + radius * Math.sin(rad),
    };
  };

  const needleEnd = polarToCartesian(((score / 100) * 180));

  return (
    <div className="glass-card-strong rounded-2xl p-5 flex flex-col h-full">
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-2">
          <Brain className="w-4 h-4 text-muted-foreground" />
          <h2 className="text-xs font-semibold uppercase tracking-widest text-muted-foreground">
            Sentiment Engine
          </h2>
        </div>
        <span className="text-[10px] font-mono font-medium px-2 py-0.5 rounded-full bg-accent text-accent-foreground">
          {model}
        </span>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center">
        <svg viewBox="0 0 200 110" className="w-full max-w-[240px]">
          {/* Background arc */}
          <path
            d="M 20 95 A 80 80 0 0 1 180 95"
            fill="none"
            stroke="hsl(var(--border))"
            strokeWidth="8"
            strokeLinecap="round"
          />
          {/* Colored segments */}
          <path
            d="M 20 95 A 80 80 0 0 1 66 35"
            fill="none"
            stroke="hsl(var(--bearish))"
            strokeWidth="8"
            strokeLinecap="round"
            opacity="0.3"
          />
          <path
            d="M 66 35 A 80 80 0 0 1 134 35"
            fill="none"
            stroke="hsl(var(--neutral))"
            strokeWidth="8"
            strokeLinecap="round"
            opacity="0.3"
          />
          <path
            d="M 134 35 A 80 80 0 0 1 180 95"
            fill="none"
            stroke="hsl(var(--bullish))"
            strokeWidth="8"
            strokeLinecap="round"
            opacity="0.3"
          />
          {/* Needle */}
          <line
            x1={cx}
            y1={cy}
            x2={needleEnd.x}
            y2={needleEnd.y}
            stroke="hsl(var(--foreground))"
            strokeWidth="2.5"
            strokeLinecap="round"
            className="transition-all duration-700 ease-out"
          />
          <circle cx={cx} cy={cy} r="4" fill="hsl(var(--foreground))" />
        </svg>

        <div className="text-center mt-2">
          <div className={`font-mono text-4xl font-bold tabular-nums number-roll ${getColor()}`}>
            {score.toFixed(1)}
          </div>
          <div className={`text-sm font-semibold mt-1 ${getColor()}`}>{getLabel()}</div>
          <div className="text-[10px] text-muted-foreground mt-1">Hybrid Sentiment Score</div>
        </div>
      </div>
    </div>
  );
};

export default SentimentGauge;

