import { Wallet, TrendingUp } from "lucide-react";
import { useEffect, useState } from "react";

const PaperWallet = () => {
  const startingCapital = 10000;
  const [currentValue, setCurrentValue] = useState(10704.95);

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentValue((prev) => {
        const delta = (Math.random() - 0.45) * 50;
        return Math.max(8000, prev + delta);
      });
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  const pnl = currentValue - startingCapital;
  const pnlPct = (pnl / startingCapital) * 100;
  const isPositive = pnl >= 0;

  return (
    <div className="glass-card rounded-2xl p-5 w-full">
      <div className="flex items-center gap-2 mb-4">
        <Wallet className="w-4 h-4 text-muted-foreground" />
        <h2 className="text-xs font-semibold uppercase tracking-widest text-muted-foreground">
          Paper Wallet
        </h2>
      </div>

      <div className="space-y-3">
        <div>
          <div className="text-[10px] text-muted-foreground mb-0.5">Current Valuation</div>
          <div className="font-mono text-2xl font-bold tabular-nums text-foreground number-roll">
            ${currentValue.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </div>
        </div>

        <div className="flex items-center gap-4">
          <div>
            <div className="text-[10px] text-muted-foreground">Starting Capital</div>
            <div className="font-mono text-sm tabular-nums text-muted-foreground">
              ${startingCapital.toLocaleString("en-US", { minimumFractionDigits: 2 })}
            </div>
          </div>
          <div>
            <div className="text-[10px] text-muted-foreground">Total P&L</div>
            <div className={`font-mono text-sm font-semibold tabular-nums flex items-center gap-1 ${
              isPositive ? "text-bullish" : "text-bearish"
            }`}>
              <TrendingUp className={`w-3 h-3 ${!isPositive && "rotate-180"}`} />
              {isPositive ? "+" : ""}${pnl.toFixed(2)} ({isPositive ? "+" : ""}{pnlPct.toFixed(2)}%)
            </div>
          </div>
        </div>

        <div className="w-full h-1.5 bg-border rounded-full overflow-hidden">
          <div
            className={`h-full rounded-full transition-all duration-700 ${isPositive ? "bg-bullish" : "bg-bearish"}`}
            style={{ width: `${Math.min(100, Math.max(5, (currentValue / 15000) * 100))}%` }}
          />
        </div>
      </div>
    </div>
  );
};

export default PaperWallet;

