import { useEffect, useState } from "react";
import { BarChart3 } from "lucide-react";

const generateSparklineData = () =>
  Array.from({ length: 30 }, () => 30 + Math.random() * 40);

const SentimentSparkline = () => {
  const [data, setData] = useState(generateSparklineData);

  useEffect(() => {
    const interval = setInterval(() => {
      setData((prev) => {
        const newPoint = Math.max(10, Math.min(90, prev[prev.length - 1] + (Math.random() - 0.5) * 12));
        return [...prev.slice(1), newPoint];
      });
    }, 2000);
    return () => clearInterval(interval);
  }, []);

  const width = 200;
  const height = 60;
  const max = Math.max(...data);
  const min = Math.min(...data);
  const range = max - min || 1;

  const points = data
    .map((val, i) => {
      const x = (i / (data.length - 1)) * width;
      const y = height - ((val - min) / range) * height;
      return `${x},${y}`;
    })
    .join(" ");

  const areaPoints = `0,${height} ${points} ${width},${height}`;
  const lastVal = data[data.length - 1];
  const trend = lastVal > data[data.length - 2] ? "bullish" : "bearish";

  return (
    <div className="glass-card rounded-2xl p-5 w-full flex flex-col">
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <BarChart3 className="w-4 h-4 text-muted-foreground" />
          <h2 className="text-xs font-semibold uppercase tracking-widest text-muted-foreground">
            Sentiment Volatility
          </h2>
        </div>
        <span className={`font-mono text-sm font-bold tabular-nums ${
          trend === "bullish" ? "text-bullish" : "text-bearish"
        }`}>
          {lastVal.toFixed(1)}
        </span>
      </div>

      <svg viewBox={`0 0 ${width} ${height}`} className="w-full flex-1" preserveAspectRatio="none">
        <defs>
          <linearGradient id="sparkGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={trend === "bullish" ? "hsl(145,100%,39%)" : "hsl(4,100%,60%)"} stopOpacity="0.2" />
            <stop offset="100%" stopColor={trend === "bullish" ? "hsl(145,100%,39%)" : "hsl(4,100%,60%)"} stopOpacity="0" />
          </linearGradient>
        </defs>
        <polygon points={areaPoints} fill="url(#sparkGrad)" />
        <polyline
          points={points}
          fill="none"
          stroke={trend === "bullish" ? "hsl(145,100%,39%)" : "hsl(4,100%,60%)"}
          strokeWidth="1.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    </div>
  );
};

export default SentimentSparkline;
